from fractions import Fraction as F
from math import factorial as fac,comb

def add_term(out,d,c):
 out[d]=out.get(d,F(0))+c
 if out[d]==0:del out[d]
def deriv(P,j,q):
 out={}
 for d,c in P.items():
  if d[j]<q:continue
  e=list(d);e[j]-=q
  add_term(out,tuple(e),c*F(fac(d[j]),fac(d[j]-q)))
 return out
def moment(p,a,n):
 return F(fac(n),fac(n//p))*a**(n//p) if n%p==0 else F(0)
def cond(P,p,a,S):
 out={}
 for d,c in P.items():
  for i in range(len(d)):
   if i not in S:c*=moment(p,a[i],d[i])
  add_term(out,tuple(d[i] if i in S else 0 for i in range(len(d))),c)
 return out
def heat(P,p,a,j):
 out={}
 for d,c in P.items():
  for k in range(d[j]//p+1):
   e=list(d);e[j]-=p*k
   add_term(out,tuple(e),c*F(fac(d[j]),fac(e[j])*fac(k))*a**k)
 return out
def clamp(P,S):
 return {d:c for d,c in P.items() if all(d[i]==0 for i in range(len(d)) if i not in S)}
def scale(P,c):return {d:v*c for d,v in P.items() if v*c}

from itertools import product

def plus(P,Q):
 out=dict(P)
 for d,c in Q.items():add_term(out,d,c)
 return out
def minus(P,Q):return plus(P,scale(Q,F(-1)))
def degree(P):return max([sum(d) for d in P]+[0])
def pull(P):
 out={}
 for d,c in P.items():
  for ks in product(*(range(di+1) for di in d)):
   e=[];v=c
   for di,ki in zip(d,ks):e.extend([ki,di-ki]);v*=comb(di,ki)
   add_term(out,tuple(e),v)
 return out
def jet(P,p,a,j,q):return scale(clamp(deriv(cond(P,p,a,set(range(j+1))),j,q),set(range(j))),F(1,fac(q)))
def innovation(J,p,a,j,q):
 out=scale(J,-moment(p,a[j],q))
 for d,c in J.items():
  e=list(d);e[j]+=q;add_term(out,tuple(e),c)
 return out
degree_checks=cell_checks=cut_checks=coefficient_checks=nonzero=0
for p in [2,4,6,8]:
 for N in [1,2]:
  for T in [F(1,2),F(1),F(3,2)]:
   a=[(-1)**(p//2+1)*T/N]*N;af=[a[0]/2]*(2*N)
   for seed in range(12):
    P={};add_term(P,tuple((seed+i)%5 for i in range(N)),F(2,3))
    add_term(P,tuple((seed+2*i+1)%4 for i in range(N)),F(-3,5))
    if seed%3==0:add_term(P,(p+2,)+(0,)*(N-1),F(1,seed+2))
    R=pull(P);D=degree(P)
    assert degree(R)<=D;degree_checks+=1
    cells=[]
    for j in range(2*N):
     c={}
     for q in range(1,D+1):c=plus(c,innovation(jet(R,p,af,j,q),p,af,j,q))
     expected=minus(cond(R,p,af,set(range(j+1))),cond(R,p,af,set(range(j))))
     assert c==expected
     assert jet(R,p,af,j,D+1)=={}
     cells.append(c);cell_checks+=1
     parent=j//2
     for q in range(p):
      Q=deriv(P,parent,q);Qfine=deriv(R,j,q)
      assert Qfine==pull(Q)
      coarse=pull(scale(cond(Q,p,a,set(range(parent))),F(1,fac(q))))
      fine=scale(cond(Qfine,p,af,set(range(j))),F(1,fac(q)))
      at_even=scale(cond(Qfine,p,af,set(range(2*parent))),F(1,fac(q)))
      assert coarse==at_even
      assert minus(fine,coarse)==scale(minus(cond(Qfine,p,af,set(range(j))),
        cond(Qfine,p,af,set(range(2*parent)))),F(1,fac(q)))
      if j%2==0:assert fine==coarse
      nonzero+=fine!=coarse;coefficient_checks+=1
    for lo in range(2*N+1):
     for hi in range(lo,2*N+1):
      c={}
      for j in range(lo,hi):c=plus(c,cells[j])
      assert c==minus(cond(R,p,af,set(range(hi))),cond(R,p,af,set(range(lo))))
      cut_checks+=1
print(dict(passed=True,refinement_degree_checks=degree_checks,common_degree_cell_identities=cell_checks,
